fn parse_codex_reconnect_progress(text: &str) -> Option<CodexReconnectProgress> {
    let counter = text.trim().strip_prefix(CODEX_RECONNECT_PROGRESS_PREFIX)?;
    let (attempt, total) = counter.split_once('/')?;
    let attempt = attempt.parse::<u32>().ok()?;
    let total = total.parse::<u32>().ok()?;
    (attempt > 0 && total > 0 && attempt <= total)
        .then_some(CodexReconnectProgress { attempt, total })
}

fn codex_terminal_http_status(text: &str) -> Option<u16> {
    let line = text.lines().map(str::trim).find(|line| !line.is_empty())?;
    let status_text = line
        .strip_prefix("unexpected status ")
        .or_else(|| line.strip_prefix("http status "))
        .or_else(|| line.strip_prefix("status "))
        .unwrap_or(line);
    let mut parts = status_text.split_ascii_whitespace();
    let first = parts.next()?;
    let status = if first.starts_with("HTTP/") {
        parts.next()?.parse::<u16>().ok()?
    } else {
        first.parse::<u16>().ok()?
    };
    parts.next()?;
    (400..=599).contains(&status).then_some(status)
}

/// Some ACP adapters surface a terminal provider failure as an ordinary
/// `agent_message_chunk` and still complete the prompt with `end_turn`.  The
/// absence of `messageId` is the strongest signal, but Codex has also emitted
/// attributed chunks for account, capacity, and upstream failures.  Keep a
/// small provider-error vocabulary here so those chunks cannot be promoted to
/// a normal final Agent message.
fn provider_terminal_error_text(text: &str) -> bool {
    if codex_terminal_http_status(text).is_some() {
        return true;
    }
    let lower = text.to_ascii_lowercase();
    let trimmed = lower.trim_start();
    if [
        "error",
        "failed",
        "failure",
        "unable to",
        "could not",
        "request failed",
        "api error",
        "network error",
        "connection error",
    ]
    .iter()
    .any(|prefix| trimmed.starts_with(prefix))
    {
        return true;
    }
    [
        "high demand",
        "at capacity",
        "insufficient account balance",
        "insufficient balance",
        "insufficient credit",
        "rate limit",
        "rate_limit",
        "too many requests",
        "quota exceeded",
        "service unavailable",
        "temporarily unavailable",
        "internal server error",
        "bad gateway",
        "gateway timeout",
        "payment required",
        "invalid api key",
        "authentication required",
        "unauthorized",
        "forbidden",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn acp_authentication_required_text(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    [
        "authentication required",
        "not authenticated",
        "not logged in",
        "login required",
        "please log in",
        "please login",
        "unauthorized",
    ]
    .iter()
    .any(|needle| text.contains(needle))
}

fn provider_authentication_required_error(
    method: &str,
    rpc_message: &str,
    stderr_summary: &str,
) -> VibexError {
    VibexError::provider(
        "provider_authentication_required",
        "Agent authentication is required",
    )
    .with_recovery_hint("Sign in from the Agent authentication settings, then retry.")
    .with_diagnostic("method", method)
    .with_diagnostic("rpcMessage", redact_summary(rpc_message))
    .with_diagnostic("stderrSummary", redact_summary(stderr_summary))
}

fn append_bounded_assistant_text(buffer: &mut String, truncated: &mut bool, text: &str) {
    if buffer.len() >= ACP_ACTIVE_MESSAGE_LIMIT {
        *truncated = true;
        return;
    }
    let remaining = ACP_ACTIVE_MESSAGE_LIMIT.saturating_sub(buffer.len());
    let mut end = text.len().min(remaining);
    while end > 0 && !text.is_char_boundary(end) {
        end -= 1;
    }
    buffer.push_str(&text[..end]);
    if end < text.len() {
        *truncated = true;
    }
}

