    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn session_runtime_config_applies_model_effort_mode_and_generic_in_order() {
        let Some(fixture) = MockAcpFixture::create("runtime-config-chain") else {
            return;
        };
        let client = fixture.client();
        let session_id = VibexSessionId::new();
        let session = client
            .create_session(AcpCreateSessionRequest {
                session_id: session_id.clone(),
                provider_profile_id: fixture.profile_id.clone(),
                model: None,
                workspace_root: fixture.workspace.display().to_string(),
                runtime_resources: ProviderRuntimeResources::default(),
            })
            .await
            .unwrap();
        let attachment = client.current_attachment(&session_id).unwrap();
        let catalog = client.session_model_catalog(&session_id).unwrap();
        assert!(!catalog.is_empty());
        assert!(catalog.iter().all(|entry| {
            entry.reasoning_efforts.is_empty() && entry.default_reasoning_effort.is_none()
        }));
        let state = attachment.payload().runtime_config_state();
        let result = client
            .update_session_runtime_config(SessionRuntimeConfigMutationRequest {
                session_id: session_id.clone(),
                expected_revision: state.state_revision,
                expected_binding_id: attachment.binding_id().clone(),
                expected_activation_generation: attachment.fence().activation_generation as i64,
                patch: SessionRuntimeConfigPatch {
                    model_id: Some("mock/model-2".to_string()),
                    reasoning_effort: Some("high".to_string()),
                    mode_id: Some("review".to_string()),
                    config_values: BTreeMap::from([("autoapply".to_string(), "false".to_string())]),
                    ..Default::default()
                },
            })
            .await
            .unwrap();
        assert_eq!(result.state.state_revision, 1, "{result:#?}");
        assert_eq!(
            result.state.effective_model.as_deref(),
            Some("mock/model-2")
        );
        assert_eq!(
            result.state.effective_reasoning_effort.as_deref(),
            Some("high")
        );
        assert_eq!(result.state.effective_mode.as_deref(), Some("review"));
        assert_eq!(
            result
                .state
                .config_values
                .get("autoapply")
                .and_then(|value| value.effective.as_ref())
                .map(|value| value.value.as_str()),
            Some("false")
        );
        assert!(
            result
                .outcomes
                .iter()
                .all(|outcome| outcome.status == SessionRuntimeConfigApplyStatus::Applied)
        );

        let methods = fixture
            .request_log()
            .into_iter()
            .filter_map(|entry| {
                entry
                    .get("method")
                    .and_then(Value::as_str)
                    .map(str::to_string)
            })
            .filter(|method| {
                matches!(
                    method.as_str(),
                    "session/set_model" | "session/set_mode" | "session/set_config_option"
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            methods,
            vec![
                "session/set_model",
                "session/set_config_option",
                "session/set_mode",
                "session/set_config_option"
            ]
        );

        let before = methods.len();
        let no_op = client
            .update_session_runtime_config(SessionRuntimeConfigMutationRequest {
                session_id: session_id.clone(),
                expected_revision: result.state.state_revision,
                expected_binding_id: attachment.binding_id().clone(),
                expected_activation_generation: attachment.fence().activation_generation as i64,
                patch: SessionRuntimeConfigPatch {
                    model_id: Some("mock/model-2".to_string()),
                    reasoning_effort: Some("high".to_string()),
                    mode_id: Some("review".to_string()),
                    config_values: BTreeMap::from([("autoapply".to_string(), "false".to_string())]),
                    ..Default::default()
                },
            })
            .await
            .unwrap();
        assert_eq!(no_op.state.state_revision, result.state.state_revision);
        assert!(
            no_op
                .outcomes
                .iter()
                .all(|outcome| outcome.status == SessionRuntimeConfigApplyStatus::NoOp)
        );
        let after = fixture
            .request_log()
            .into_iter()
            .filter(|entry| {
                matches!(
                    entry.get("method").and_then(Value::as_str),
                    Some("session/set_model")
                        | Some("session/set_mode")
                        | Some("session/set_config_option")
                )
            })
            .count();
        assert_eq!(before, after);

        let binding_id = attachment.binding_id().clone();
        assert!(
            client
                .runtime_config_states
                .lock()
                .unwrap()
                .contains_key(&binding_id)
        );
        let binding = test_binding_for(&session_id, &fixture.profile_id, &session);
        client.close_session(&binding).await.unwrap();
        assert!(
            !client
                .runtime_config_states
                .lock()
                .unwrap()
                .contains_key(&binding_id)
        );
        fixture.cleanup();
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn config_option_update_replaces_withdrawn_options_and_profile_evidence() {
        let Some(fixture) = MockAcpFixture::create("config-option-update-replace") else {
            return;
        };
        let client = fixture.client();
        let session_id = VibexSessionId::new();
        let session = client
            .create_session(AcpCreateSessionRequest {
                session_id: session_id.clone(),
                provider_profile_id: fixture.profile_id.clone(),
                model: None,
                workspace_root: fixture.workspace.display().to_string(),
                runtime_resources: ProviderRuntimeResources::default(),
            })
            .await
            .unwrap();
        let attachment = client.current_attachment(&session_id).unwrap();
        let payload = attachment.payload();
        payload.replace_config_options(&json!({
            "configOptions": [{
                "id": "thought_level",
                "category": "thought_level",
                "label": "Thought level",
                "type": "select",
                "currentValue": "high",
                "options": [
                    { "value": "low", "label": "Low" },
                    { "value": "high", "label": "High" }
                ]
            }]
        }));

        let planner = {
            let state = payload.state.lock().unwrap();
            let discovery = state.session_config_state.as_ref().unwrap();
            assert_eq!(discovery.options.len(), 1);
            assert_eq!(discovery.options[0].id, "thought_level");
            assert!(discovery.models.is_empty());
            assert!(discovery.modes.is_empty());
            assert!(discovery.current_model.is_none());
            assert!(discovery.current_mode.is_none());
            assert!(state.model_ids.is_empty());
            assert!(state.current_model_id.is_none());
            assert!(state.current_mode_id.is_none());
            state.session_config_planner.clone().unwrap()
        };

        let stale_key =
            crate::session_config::CanonicalSessionConfigKey::parse("autoApply").unwrap();
        let current_key =
            crate::session_config::CanonicalSessionConfigKey::parse("thought_level").unwrap();
        assert!(planner.option_for_key(&stale_key).unwrap().is_none());
        assert!(planner.option_for_key(&current_key).unwrap().is_some());

        let evidence = client.profile_session_config_evidence().unwrap();
        let profile_evidence = evidence.get(&fixture.profile_id).unwrap();
        assert!(profile_evidence.models.is_empty());
        assert!(profile_evidence.modes.is_empty());
        assert_eq!(profile_evidence.options.len(), 1);
        assert_eq!(
            profile_evidence
                .reasoning_efforts
                .iter()
                .map(|effort| effort.value.as_str())
                .collect::<Vec<_>>(),
            vec!["low", "high"]
        );

        let binding = test_binding_for(&session_id, &fixture.profile_id, &session);
        client.close_session(&binding).await.unwrap();
        fixture.cleanup();
    }

