    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn mock_acp_agent_probe_lists_models() {
        let Some(fixture) = MockAcpFixture::create("probe") else {
            return;
        };
        fixture.enable_model_config_updates();
        let client = AcpRuntimeClient::new(ProviderConfigService::new(fixture.db_path.clone()));

        let probed = client
            .probe_runtime_session_config(&fixture.profile_id)
            .await
            .unwrap();

        assert_eq!(
            probed.models,
            vec!["mock/model-1".to_string(), "mock/model-2".to_string()]
        );
        assert_eq!(
            probed
                .modes
                .iter()
                .map(|mode| (mode.value.as_str(), mode.label.as_deref()))
                .collect::<Vec<_>>(),
            vec![("build", Some("Build")), ("review", Some("Review"))]
        );
        assert_eq!(
            probed
                .reasoning_efforts
                .iter()
                .map(|effort| effort.value.as_str())
                .collect::<Vec<_>>(),
            vec!["low", "medium", "high"]
        );

        let models = client
            .list_runtime_models(&fixture.profile_id)
            .await
            .unwrap();
        assert_eq!(models, probed.models);

        let model_probe = client
            .probe_runtime_session_config_for_model(&fixture.profile_id, "mock/model-2")
            .await
            .unwrap();
        assert_eq!(model_probe.models, vec!["mock/model-2".to_string()]);
        assert_eq!(
            model_probe
                .reasoning_efforts
                .iter()
                .map(|effort| effort.value.as_str())
                .collect::<Vec<_>>(),
            vec!["none", "on"]
        );
        assert_eq!(
            model_probe
                .modes
                .iter()
                .map(|mode| mode.value.as_str())
                .collect::<Vec<_>>(),
            vec!["build", "review"]
        );
        let model_request = fixture
            .request_log()
            .into_iter()
            .find(|entry| entry["method"] == "session/set_config_option")
            .expect("model-scoped probe must select its target model");
        assert_eq!(model_request["params"]["configId"], "model");
        assert_eq!(model_request["params"]["value"], "mock/model-2");
        fixture.cleanup();
    }

